from chapter09_common import *
B=Block('b')
NUMERIC=[]
def verify(name,a,b):
 assert math.isclose(a,b,rel_tol=1e-9,abs_tol=1e-9),(name,a,b)
 NUMERIC.append(name)
def angle(p,a,o,b):
 u=subv(p[a],p[o]);v=subv(p[b],p[o]);return math.degrees(math.acos(max(-1,min(1,sum(u[i]*v[i] for i in (0,1))/(dist(p[a],p[o])*dist(p[b],p[o]))))))
def area(p,ns):return abs(sum(p[ns[i]][0]*p[ns[(i+1)%len(ns)]][1]-p[ns[(i+1)%len(ns)]][0]*p[ns[i]][1] for i in range(len(ns))))/2
def cp(angles,r=5):return dict(O=[0,0],**{k:polar([0,0],v,r) for k,v in angles.items()})
def cv(ps='ABC',segments=None,through='A',**kw):return sc(ps,[['A','B'],['B','C']] if segments is None else segments,circles=[circle('O',through)],**kw)
def oncircle(ps):return equal(*[('O',n) for n in ps])
def put(n,part,condition,answer,steps,p,v,views=None,**kw):
 printed=kw.pop('printed',[205] if n<=778 else [206] if n<=783 else [208] if n<=789 else [209])
 B.add(n,part,condition,answer,steps,p,v,views,printed=printed,**kw)
