# Tangential quadrilaterals: intersections of genuine tangent lines.
def tangent_polygon(normals,r=3):
 q={'O':[0,0]};ts=[polar([0,0],t,r) for t in normals];ns=[polar([0,0],t,1) for t in normals]
 for i in range(len(normals)):
  a=ts[i-1];u=[-ns[i-1][1],ns[i-1][0]];b=ts[i];v=[-ns[i][1],ns[i][0]]
  q[chr(65+i)]=inter(a,addv(a,u),b,addv(b,v));q['_T'+str(i)]=ts[i]
 return q
def perimeter(p,ns):return sum(dist(p[ns[i]],p[ns[(i+1)%len(ns)]]) for i in range(len(ns)))
def tangent_checks(p,ns):
 out=[]
 for i,a in enumerate(ns):
  c=ns[(i+1)%len(ns)];t='_T'+str(i);out += [col(a,t,c),perp('O',t,a,c)]
 out.append(equal(*[('O','_T'+str(i)) for i in range(len(ns))]));return out
